#include "server1/archive/ArchiveSources.h"
#include <QCoreApplication>
#include <QFile>
#include <QJsonDocument>
#include <iostream>
using namespace server1::archive;
int main(int argc,char **argv) {
 QCoreApplication app(argc,argv); QFile f(argv[1]); if(!f.open(QIODevice::ReadOnly))return 2;auto root=QJsonDocument::fromJson(f.readAll()).object(); int failures=0;
 auto check=[&](bool ok,const QString &s){if(!ok){std::cerr<<s.toStdString()<<'\n';++failures;}};
 for(auto row:root["rows"].toArray()){auto r=row.toObject(),e=r["expected"].toObject();QString family=r["family"].toString();auto kind=family=="rar"?SourceFamily::Rar:family=="zip"?SourceFamily::Zip:family=="7z"?SourceFamily::SevenZip:family=="tar"?SourceFamily::Tar:SourceFamily::Gzip;QList<qint64> prior;for(auto x:r["lengths"].toArray())prior.append(x.toInteger());auto d=describeSource(kind,r["url"],prior,r["isLast"].toBool());check(d.name==e["name"].toString(),"name "+family);check(d.length.has_value()==(e["probes"].toInt()==0),"inference "+family);qint64 len=d.length.value_or(90);check(len==e["length"].toInteger(),"length");QList<QJsonObject> ranges{{},{{"start",0},{"end",0}},{{"start",2},{"end",5}},{{"start",2},{"end",999}},{{"end",5}},{{"start",2}}};auto calls=e["calls"].toArray();for(int i=0;i<ranges.size();++i)check(sourceRangeHeader(len,ranges[i])==calls[i].toObject()["range"].toString().toUtf8(),"range "+family);}
 for(auto v:root["lz"].toArray()){auto o=v.toObject();check(decompressUriQuery(o["encoded"].toString())==o["input"].toString(),"LZ");}
 for(auto v:root["keys"].toArray()){auto o=v.toObject();auto f=o["family"].toString();ArchiveKeys k(f=="rar"?SourceFamily::Rar:f=="zip"?SourceFamily::Zip:f=="7zip"?SourceFamily::SevenZip:f=="tar"?SourceFamily::Tar:SourceFamily::Gzip);auto r=k.create("GET",{}, {},o["encoded"].toString());check(r.status==o["status"].toInt()&&r.location==o["location"].toString(),"key redirect "+f+" actual "+r.location+" expected "+o["location"].toString());check(k.get(r.key)==std::optional<QJsonArray>(o["values"].toArray()),"key normalization "+f);}
 for(auto v:root["multipart"].toArray()){auto o=v.toObject();QList<qint64> ls;for(auto n:o["lengths"].toArray())ls<<n.toInteger();QString error;auto parts=multipartRanges(ls,o["start"].toInteger(),o["end"].toInteger(),&error);auto expected=o["parts"].toArray();bool ok=error.isEmpty()&&parts.size()==expected.size()&&multipartLength(ls)==o["length"].toInteger();for(int i=0;ok&&i<parts.size();++i){auto p=expected[i].toObject();ok=parts[i].part==p["part"].toInt()&&parts[i].start==p["start"].toInteger()&&parts[i].end==p["end"].toInteger();}check(ok,"multipart differential");}
 ArchiveKeys keys(SourceFamily::Zip);auto k=keys.create("POST",QJsonArray{"a.zip","b.z2","c.z01","d.z2"},"fixed");check(k.status==200&&k.key=="fixed","create");auto urls=keys.get("fixed");check(urls&&(*urls)[0]=="c.z01"&&(*urls)[1]=="b.z2"&&(*urls)[2]=="d.z2"&&(*urls)[3]=="a.zip","stable ordering");keys.create("POST",QJsonArray{"changed"},"fixed");check(keys.get("fixed")==urls,"idempotent custom key");check(!keys.get("missing"),"missing key");check(keys.create("POST",QJsonObject{}).error=="Cannot parse JSON data, err 1","invalid body");check(keys.create("GET",{}).error=="Cannot parse JSON data, err 2","missing lz");check(keys.create("GET",{}, {},"malformed").status==500,"invalid lz");
 check(multipartLength({10,10})==18,"multipart source length");QString error;auto parts=multipartRanges({10,10},8,12,&error);check(error.isEmpty()&&parts.size()==2&&parts[0].start==8&&parts[0].end==9&&parts[1].start==0&&parts[1].end==2,"multipart mapping");
 std::cout<<"failures="<<failures<<'\n';return failures?1:0;
}
